package com.familygrowth.application;
import com.familygrowth.domain.Stage3Models.Actor;import com.familygrowth.domain.Stage26DataRightsModels.*;import java.security.*;import java.nio.charset.StandardCharsets;import java.time.*;import java.util.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service @Transactional public class Stage26DataRightsService {private static final List<String> RETAINED=List.of("去标识化 Wallet/Ledger 与费用流水","去标识化 Assignment/Completion 最小状态","RBAC、审计、幂等和安全事件最小事实");private static final List<String> REDACTED=List.of("姓名、生日和个性化学段配置","目标、复盘、证据说明和求助自由文本","未完成愿望、兴趣和有效儿童会话");private final Stage3Service auth;private final Stage26DataRightsStore store;private final Clock clock;private final SecureRandom random=new SecureRandom();public Stage26DataRightsService(Stage3Service auth,Stage26DataRightsStore store,Clock clock){this.auth=auth;this.store=store;this.clock=clock;}
 public ChildDataExport export(Actor actor,UUID family,UUID child,String key){auth.requireParent(actor,family);auth.requireChildOrParent(actor,family,child);validKey(key);String payload=hash(child+"|EXPORT");var old=store.byKey(family,key);UUID request;if(old.isPresent()){same(old.get(),child,"EXPORT",payload);request=old.get().id();}else request=store.create(family,child,actor.actorId(),"EXPORT",null,null,key,payload,clock.instant()).id();Map<String,Object> f=store.exportFacts(family,child);store.recordExport(family,child,request,actor.actorId(),clock.instant());return new ChildDataExport("family-growth-child-export/1",family,child,clock.instant(),map(f,"profile"),map(f,"learning"),map(f,"usage"),map(f,"finance"),List.of("PIN/Token/secret","答案键","家长私密说明"));}
 public ErasurePreview preview(Actor actor,UUID family,UUID child,String key){auth.requireParent(actor,family);auth.requireChildOrParent(actor,family,child);validKey(key);String payload=hash(child+"|ERASURE");var old=store.byKey(family,key);if(old.isPresent()){same(old.get(),child,"ERASURE",payload);throw new Stage3Service.ConflictException("Erasure preview token is shown only once; create a new preview");}byte[] b=new byte[32];random.nextBytes(b);String token=Base64.getUrlEncoder().withoutPadding().encodeToString(b);Instant expires=clock.instant().plus(Duration.ofMinutes(10));StoredRequest r=store.create(family,child,actor.actorId(),"ERASURE",hash(token),expires,key,payload,clock.instant());return new ErasurePreview(r.id(),child,REDACTED,RETAINED,expires,token);}
 public ErasureResult confirm(Actor actor,UUID family,UUID child,UUID request,String token,String pin){auth.requireParent(actor,family);auth.requireChildOrParent(actor,family,child);auth.verifyParentPin(actor,pin);StoredRequest r=store.byId(family,request).orElseThrow(FamilyGrowthService.NotFoundException::new);if(!r.childId().equals(child)||!r.type().equals("ERASURE"))throw new FamilyGrowthService.NotFoundException();if(r.status().equals("COMPLETED"))return new ErasureResult(r.id(),child,"COMPLETED",r.completedAt(),RETAINED);if(token==null||!MessageDigest.isEqual(hash(token).getBytes(StandardCharsets.UTF_8),r.tokenHash().getBytes(StandardCharsets.UTF_8))||r.tokenExpiresAt().isBefore(clock.instant()))throw new IllegalArgumentException("Erasure confirmation is invalid or expired");StoredRequest done=store.completeErasure(family,child,request,actor.actorId(),clock.instant());return new ErasureResult(done.id(),child,"COMPLETED",done.completedAt(),RETAINED);}
 @SuppressWarnings("unchecked")private static Map<String,Object> map(Map<String,Object> all,String key){return (Map<String,Object>)all.getOrDefault(key,Map.of());}private static void same(StoredRequest r,UUID child,String type,String payload){if(!r.childId().equals(child)||!r.type().equals(type)||!r.payloadHash().equals(payload))throw new Stage3Service.ConflictException("Idempotency-Key was used for another data request");}private static void validKey(String k){if(k==null||k.isBlank()||k.length()>120)throw new IllegalArgumentException("Valid Idempotency-Key is required");}private static String hash(String v){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(v.getBytes(StandardCharsets.UTF_8)));}catch(NoSuchAlgorithmException e){throw new IllegalStateException(e);}}
}
